def components(edges):
    adjacency=[set() for _ in range(4)]
    for a,b in edges:adjacency[a].add(b);adjacency[b].add(a)
    unseen=set(range(4));groups=[]
    while unseen:
        root=min(unseen);todo=[root];seen={root}
        while todo:
            u=todo.pop()
            for v in adjacency[u]-seen:seen.add(v);todo.append(v)
        unseen-=seen;groups.append(sorted(v+1 for v in seen))
    return groups
chain=[(0,1),(1,2),(2,3)]
print('节点/边/连通分量:',4,len(chain),components(chain))
print('断中间边:',components([(0,1),(2,3)]))
print('路径边数:',len([1,2,3,4])-1,'生成树边数:',4-1,'补一边圈边数:',len(chain)+1)
